import os
import shutil
import stat
import sys
import tarfile
import tempfile

BASE = os.path.realpath(os.path.join(os.path.dirname(__file__), os.pardir))
INCOMING = os.path.join(BASE, "incoming")


def fail(message):
    sys.stderr.write("unpack: %s\n" % message)
    sys.exit(1)


def safe_parts(name):
    if not isinstance(name, str) or "\0" in name:
        fail("invalid member name")
    if name.startswith("/") or os.path.isabs(name):
        fail("absolute member path rejected: %s" % name)
