    for part in name.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            fail("parent traversal rejected: %s" % name)
        result.append(part)
    return result


def checked_existing_path(root, parts):
    path = root
    for index in range(len(parts)):
        path = os.path.join(path, parts[index])
        try:
            mode = os.lstat(path).st_mode
        except OSError:
            return
        if stat.S_ISLNK(mode):
            fail("destination symlink rejected: %s" % "/".join(parts[:index + 1]))
        if index < len(parts) - 1 and not stat.S_ISDIR(mode):
            fail("destination parent is not a directory: %s" % "/".join(parts[:index + 1]))


def ensure_directory(path):
    if os.path.exists(path):
        mode = os.lstat(path).st_mode
        if stat.S_ISLNK(mode) or not stat.S_ISDIR(mode):
            fail("unsafe destination path: %s" % path)
        return
    parent = os.path.dirname(path)
    if parent != path:
        ensure_directory(parent)
    os.mkdir(path, 0755)


def main():
