        fail("usage: unpack ARCHIVE")
    archive_stream = None
    archive = None
    stage = None
    try:
        archive_stream = open(sys.argv[1], "rb")
        archive = tarfile.open(fileobj=archive_stream, mode="r:*")
        members = archive.getmembers()

        # Validate the complete archive before creating or installing a member.
        prepared = []
        for member in members:
            parts = safe_parts(member.name)
            if member.issym() or member.islnk():
                fail("link member rejected: %s" % member.name)
            if not member.isdir() and not member.isfile():
                fail("special member rejected: %s" % member.name)
            if not parts:
                if member.isdir():
                    continue
                fail("empty member path rejected")
            prepared.append((member, parts))

        if not os.path.isdir(INCOMING):
            os.mkdir(INCOMING, 0755)
        elif stat.S_ISLNK(os.lstat(INCOMING).st_mode):
            fail("incoming directory is a symlink")

        # Validate every existing destination path before installing anything.
        for member, parts in prepared:
            checked_existing_path(INCOMING, parts)

        stage = tempfile.mkdtemp(prefix=".unpack-", dir=BASE)
        for member, parts in prepared:
            target = os.path.join(stage, *parts)
            if member.isdir():
                ensure_directory(target)
            else:
                ensure_directory(os.path.dirname(target))
                source = archive.extractfile(member)
                if source is None:
                    fail("cannot read member: %s" % member.name)
                output = open(target, "wb")
                try:
                    while True:
                        block = source.read(65536)
                        if not block:
                            break
                        output.write(block)
                finally:
                    output.close()
                    source.close()
                os.chmod(target, member.mode & 0777)

        # Install only after the full archive passed preflight and staged safely.
        for member, parts in prepared:
            if member.isdir():
                ensure_directory(os.path.join(INCOMING, *parts))
        for member, parts in prepared:
            if member.isfile():
                destination = os.path.join(INCOMING, *parts)
                ensure_directory(os.path.dirname(destination))
                os.rename(os.path.join(stage, *parts), destination)
        return 0
    except (IOError, OSError, tarfile.TarError), error:
        fail(str(error))
    finally:
        if archive is not None:
            archive.close()
        if archive_stream is not None:
            archive_stream.close()
        if stage is not None and os.path.isdir(stage):
            shutil.rmtree(stage)


if __name__ == "__main__":
    sys.exit(main())
